SELECT CASE WHEN c.credit_limit >= 13700 THEN 'high' WHEN c.credit_limit >= 6600 THEN 'mid' ELSE 'low' END AS credit_limit_bucket, YEAR(c.signup_date) AS signup_year, MAX(t.amount) AS max_amount FROM transactions t INNER JOIN accounts a ON t.account_id = a.id INNER JOIN customers c ON c.id = a.customer_id GROUP BY CASE WHEN c.credit_limit >= 13700 THEN 'high' WHEN c.credit_limit >= 6600 THEN 'mid' ELSE 'low' END, YEAR(c.signup_date);
